/**
 * `popost video music quote` and `popost video music make`: background music generated by popost.ai (music/hosted.ts),
 * paid in credits by its length. `quote` prices a length (free). `make` prices the track first: without --confirm, or
 * above --max-credits, it prints the price with exit code 3 and charges nothing; with them it makes the track under
 * the project's task, waits for it and writes the MP3, which the fill then names as its "sound".
 */
import type { ParsedArgs } from '../../args';
import { isFile, printJson } from '../../core/util';
import { PopostApiError } from '../../providers/errors';
import { aroundPath } from '../../providers/task';
import type { Runtime } from '../../runtime';
import { connected, quoteMusic } from '../hosted-api';
import { probe } from '../media/ffmpeg';
import { MAX_SECONDS, MIN_SECONDS, MusicRejected, PROMPT_MAX, makeMusic, musicPrice, musicSeconds } from '../music/hosted';
import { parseProject } from '../project/schema';
import { timelineOf } from '../timeline/spans';
import { PriceNotAgreed, type PriceItem } from '../wallet';
import { CREDIT_OPTIONS, OVER, walletFor } from './credits';
import { command, PROJECT_OPTION, userPath, VideoCommandError, type Commands } from './shared';

const NOT_CONNECTED = 'Generated music needs a connected popost.ai account: popost auth login. Without one, use a sound file of the user\'s own as the fill\'s "sound", or none.';
const REJECTED_FIX = 'Describe the music by genre, mood, tempo and instruments only: no name of an artist, band, song, album or label, and no lyrics.';

/** The length of a video file, or of a project's video.json, in seconds. */
const videoSeconds = async (rt: Runtime, file: string): Promise<number> => {
  if (!(await isFile(rt, file))) throw new VideoCommandError('There is no file at ' + file + '. Check the path; a relative one is read from ' + rt.cwd + '.');
  if (rt.path.extname(file).toLowerCase() !== '.json') return (await probe(rt, file)).duration;
  const { project } = parseProject(JSON.parse(await rt.fs.readText(file)) as unknown);
  if (!project) throw new VideoCommandError(file + ' is not a video project; run popost video check on its folder first.');
  return timelineOf(project).total / project.canvas.fps;
};

/**
 * The seconds of music to ask for: --seconds, else the length of --video (a video file), else the length of the
 * project (--project, its video.json); rounded up to a whole second, 3 at least and 300 at most.
 */
const secondsOf = async (rt: Runtime, o: { seconds?: number; video?: string; project?: string }): Promise<{ seconds: number; of: number }> => {
  if (o.seconds !== undefined && !(o.seconds > 0)) throw new VideoCommandError('--seconds is the length of the video in seconds, above 0.');
  const of = o.seconds ?? (o.video !== undefined ? await videoSeconds(rt, userPath(rt, o.video)) : o.project !== undefined ? await videoSeconds(rt, rt.path.join(userPath(rt, o.project), 'video.json')) : undefined);
  if (of === undefined || !(of > 0)) throw new VideoCommandError('Give the length: --seconds N, --video <a video file as long as the music should be>, or --project <a project with a video.json>.');
  return { seconds: musicSeconds(of), of };
};

const lengthArgs = (args: ParsedArgs): { seconds?: number; video?: string; project?: string } => {
  const seconds = args.number('seconds'), video = args.string('video'), project = args.string('project');
  return { ...(seconds !== undefined ? { seconds } : {}), ...(video !== undefined ? { video } : {}), ...(project !== undefined ? { project } : {}) };
};

/** What to say when the video is longer than a track can be, or shorter than the shortest one. */
const lengthNote = (of: number): { note?: string } =>
  of > MAX_SECONDS ? { note: 'A track is at most ' + MAX_SECONDS + ' s and is not repeated: the video has music for its first ' + MAX_SECONDS + ' s, faded out there, and none after.' }
    : of < MIN_SECONDS ? { note: 'A track is at least ' + MIN_SECONDS + ' s: the video uses its beginning and fades it out at its end.' } : {};

const LENGTH_OPTIONS = [
  { flag: '--seconds', kind: 'number', metavar: 'N', help: 'the length of the video in seconds; rounded up to a whole second, ' + MIN_SECONDS + ' to ' + MAX_SECONDS } as const,
  { flag: '--video', metavar: 'FILE', help: 'instead of --seconds: a video file as long as the music should be (the reference, a render)' },
];

const quote = command(
  'what generated background music of a length costs on popost.ai, in credits; charges nothing',
  { options: [...LENGTH_OPTIONS, { ...PROJECT_OPTION, help: 'instead of --seconds: a video project; the music is as long as its video.json' }] },
  async (args, rt) => {
    if (!connected(rt)) throw new VideoCommandError(NOT_CONNECTED);
    const { seconds, of } = await secondsOf(rt, lengthArgs(args));
    printJson(rt, { ok: true, seconds, credits: await quoteMusic(rt, seconds), ...lengthNote(of), next: 'Show the user the music plan (style, length, under the voice or alone) with these credits before popost video music make.' });
  },
);

const refused = (rt: Runtime, e: MusicRejected): number => {
  const fix = REJECTED_FIX + (e.suggestion ? ' popost.ai suggests: "' + e.suggestion + '". Run the command again with it as --prompt: the same price, and the refused try was not charged.' : ' Write it again and run the command with the new --prompt: the refused try was not charged.');
  printJson(rt, { ok: false, error: e.message, problems: [{ level: 'error', at: '--prompt', message: 'The description names an artist, a band, a song, an album or a label, quotes lyrics, or asks for something that is not allowed.', fix }], ...(e.suggestion ? { suggestion: e.suggestion } : {}), chargedCredits: 0 });
  return 2;
};

/** A price the platform found above maxCredits after the quote fitted: the same answer as a quote above --max-credits. */
const overLimit = (e: unknown, items: readonly PriceItem[], max: number): never => {
  if (!(e instanceof PopostApiError && e.code === 'CREDIT_LIMIT_EXCEEDED')) throw e;
  const required = typeof e.details.required === 'number' ? e.details.required : items.reduce((n, i) => n + i.credits, 0);
  throw new PriceNotAgreed({ credits: required, items: items.map((i) => ({ ...i, credits: required })), maxCredits: max }, OVER);
};

const make = command(
  'generate background music on popost.ai from a description (genre, mood, tempo, instruments; no artist, song or lyrics) and write it as an MP3 for the fill\'s "sound"; priced by its length: without --confirm the price is printed with exit code 3 and nothing is charged. The same command again reads the track already paid for',
  {
    options: [
      { flag: '--prompt', required: true, metavar: 'TEXT', help: 'the music in plain words: genre, mood, tempo, instruments; at most ' + PROMPT_MAX + ' characters, without the name of an artist, band, song, album or label and without lyrics' },
      ...LENGTH_OPTIONS,
      { flag: '--out', required: true, metavar: 'MP3', help: 'where the track goes: <project>/assets/music.mp3; its receipt is written beside it (.music.json)' },
      { flag: '--vocals', kind: 'flag', help: 'music with a singing voice; default instrumental, which is what goes under a voice-over' },
      { ...PROJECT_OPTION, help: 'the video project this is for: the charge joins its line on the account page, and without --seconds the music is as long as its video.json (default: the project around --out)' },
      ...CREDIT_OPTIONS,
    ],
  },
  async (args, given) => {
    const out = userPath(given, args.req('out'));
    const rt = given.project ? given : await aroundPath(given, out);
    if (!connected(rt)) throw new VideoCommandError(NOT_CONNECTED);
    const prompt = args.req('prompt').trim();
    if (!prompt || prompt.length > PROMPT_MAX) throw new VideoCommandError('--prompt describes the music in 1 to ' + PROMPT_MAX + ' characters: genre, mood, tempo, instruments.');
    if (rt.path.extname(out).toLowerCase() !== '.mp3') throw new VideoCommandError('--out is an MP3 file: write <project>/assets/music.mp3.');
    // Without a length of its own the music is as long as the project it is for (--project, else the one around --out).
    const length = lengthArgs(args);
    const { seconds, of } = await secondsOf(rt, length.seconds === undefined && length.video === undefined && rt.project ? { project: rt.project.dir } : length);
    const order = { prompt, seconds, vocals: args.flag('vocals'), out };
    const items = await musicPrice(rt, order);
    const wallet = await walletFor(rt, args, items);
    try {
      const made = await makeMusic(rt, order, wallet).catch((e: unknown) => overLimit(e, items, wallet.max));
      const sound = rt.project ? rt.path.relative(rt.project.dir, out).split(rt.path.sep).join('/') : args.req('out');
      printJson(rt, {
        ok: true, file: args.req('out'), seconds: made.seconds, chargedCredits: made.chargedCredits, instrumental: !order.vocals,
        ...(made.kept ? { kept: true } : {}), ...lengthNote(of),
        next: 'Write "sound": "' + sound + '" into the fill and run template fill again with the options it had.',
      });
    } catch (e) {
      if (e instanceof MusicRejected) return refused(rt, e);
      throw e;
    }
  },
  (args) => args.string('project'),
);

export const musicCommands: Commands = { quote, make };
